) AS (
  VALUES 
    (695::BIGINT, 'Si califica bastante duro pero en general explica bastante bien, las clases se volvían amenas incluso divertidas a veces. Cuando recibí clases con él nos ayudo bastante con los exámenes y proyectos. Lo recomiendo, eso sus proyectos si hay que dedicarle trabajo.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Brinda apoyo']::TEXT[], '2026-07-24T00:00:00+00:00'::TIMESTAMPTZ, '1a06b99f6e53c830b5b017ad3c207d353de089283c38f81f9881f8f4aab6db88'::TEXT, ARRAY[2961]::BIGINT[]),
    (695::BIGINT, 'Considero que Milton es muy buen profesor, noto que es de los pocos que hace que este curso no sea tan confuso, sin embargo si se puede decir que es algo desorganizado con las entregas de los trabajos y la publicación de las rubricas. Es un docente sumamente comprensivo y da bastante apoyo.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'La participación importa']::TEXT[], '2026-06-03T00:00:00+00:00'::TIMESTAMPTZ, 'fd304532575d6d18063a2cc4e954287694c18f558098d26dc85773bd4d7f2728'::TEXT, ARRAY[2961]::BIGINT[]),
    (695::BIGINT, 'El profesor a pesar de que sabe mucho, es muy desorganizado, no se tienen indicaciones claras en ningún trabajo, lo que hace que se deba de poner el doble de esfuerzo para pasar el curso'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2024-01-25T00:00:00+00:00'::TIMESTAMPTZ, '1e982c01b2f8c9cb53d82433082b6dddddb72697df7db23b6970ce25d4e8e6ba'::TEXT, ARRAY[2961]::BIGINT[]),
    (695::BIGINT, 'Es un pésimo profesor en muchos aspectos. Solo lee presentaciones y aún así logra hacerlas confusas. Deja tareas,de las cuales nunca se tiene la rúbrica a evaluar y las explica re mal. Usa como excusa que es coordinador de la carrera para ser un pésimo profesor. No usa TD, usa google classroom :('::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos']::TEXT[], '2023-12-30T00:00:00+00:00'::TIMESTAMPTZ, '2449bec0e78739ff37cc3bd1cf7d7c8d973396d4320477f44ecbc33789215c69'::TEXT, ARRAY[2969]::BIGINT[]),
    (695::BIGINT, 'En ningún momento dió una tabla de evaluaciones para conocer la nota del curso, manda tareas hechas a mano y quita puntos si no se ponen referencias bibliográficas cuando nisiquiera las pidió en primer lugar y su asistente revisa todo por él. El curso es pasable con él pero dejelo de última opción.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2023-12-05T00:00:00+00:00'::TIMESTAMPTZ, '642a353789b5223a57a53444042ca044714992d518d2405d61a5dda799ade44e'::TEXT, ARRAY[2969]::BIGINT[]),
    (695::BIGINT, 'Malo malo malo, no entiendo como es profesor. Deberian de llevarlo al DOP'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-11-27T00:00:00+00:00'::TIMESTAMPTZ, '6cda97884026f600fcb688d24f924083a5f8ab1e718f0b2bc88734c3e3eac694'::TEXT, ARRAY[2969]::BIGINT[]),
    (695::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-11-23T00:00:00+00:00'::TIMESTAMPTZ, 'a2ac00915a53f1381bd2ad9c86766df7478d07122f624b8e93c04d702e14adeb'::TEXT, ARRAY[1163]::BIGINT[]),
    (695::BIGINT, 'jajaja xd risa lol risa lel risa lol. No se puede tomar en serio, mal profesor, mala persona y mal coordinador de carrera. Mejor evitarlo. La materia es demasiado importante en la carrera como para desperdiciarla con un profesor así.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2023-11-20T00:00:00+00:00'::TIMESTAMPTZ, 'c3f54b2ce57bd068b35de6b2ab0004d7116b1bd8be95a94a6a67cf6f6cf5c186'::TEXT, ARRAY[2969, 2961]::BIGINT[]),
    (695::BIGINT, 'Pasa demasiado ocupado siendo coordinador de la carrera que es una basura como profesor. Explica demasiado mal, se distrae y se ciñe con un estudiante, quita la motivación, no da retroalimentación, no da rúbrica, se inventa qué calificar y después lo suena a uno.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas']::TEXT[], '2023-11-16T00:00:00+00:00'::TIMESTAMPTZ, 'e425aa3b7bbbfc36045e27f27e0c246c3250aca230a17d9cb2f4de5c05f9e13b'::TEXT, ARRAY[2969]::BIGINT[]),
    (695::BIGINT, 'El profesor se distrae con facilidad, como no es el coordinador del curso, interpreta como quiere la evaluación hecha por el coordinador. Da muy poca retroalimentación y hace que el curso aunque no sea difícil, sea un dolor de cabeza y dé mucho estrés.'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2023-10-18T00:00:00+00:00'::TIMESTAMPTZ, '5c43c304bfc3b0847645292e58d8ee851d18834cbb205cd88a21519675bb359f'::TEXT, ARRAY[2969]::BIGINT[]),
    (695::BIGINT, 'Milton es probablemente la mejor opción si piensa ponerle bastante al curso, con él se aprende un montón y es una persona que se preocupa bastante por su aprendizaje. Además, los asistentes son muy buena nota.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-17T00:00:00+00:00'::TIMESTAMPTZ, '679095d478f413a8443a8ff0df6cf46b2f8c8925e85b9af8a6e8550efc19b375'::TEXT, ARRAY[2511, 2513]::BIGINT[]),
    (695::BIGINT, 'Su experiencia con Milton depende mucho de que tantas ganas le ponga en el curso, repase mucho, ponga atención a lo que dice que va a entrar en examenes o quices porque de fijo entra, haga las tareas morales. Vaya a los talleres o las actividades fuera de clase.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2022-12-07T00:00:00+00:00'::TIMESTAMPTZ, '32e3be983bc18f5a052188864c8f0fdc47b2f2003f3530b0a05511df1c829bb5'::TEXT, ARRAY[2511]::BIGINT[]),
    (695::BIGINT, 'la gente que dice quees bueno es porque paso el curso, la que dice que es malo se quedo o lo dejo botado. no explica claro, tiene que ponerle muchisimo al curso fuera de clase para pasar con buena nota (o bueno pasar), si ve el interes y que cumple con todo hasta el final ayuda con las notas'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, '65f271e9f1c9657a94c02673af81c3e7137e25c569d3e0b92c79f4ad7a655fb0'::TEXT, ARRAY[2511, 2513]::BIGINT[]),
    (695::BIGINT, 'Milton sabe demasiado, si usted sabe aprovecharlo como profe va a valer demasiado la pena. Sin embargo el muchachon hace examenes bastante complicados y espera de usted una curva de aprendizaje muy abrupta. Si quiere ponerle ganas al curso meta con Milton, va a valer la pena'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Da crédito extra']::TEXT[], '2022-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'a140be6da1409e68fd8a83013aefd40c7b0c820c8ed4784bf08553e86e198c00'::TEXT, ARRAY[2511, 2513]::BIGINT[]),
    (695::BIGINT, 'No pierda el tiempo matriculando con el, su forma de explicar es muy confusa literal no explica solo lee lo que puso en la diapositiva, el material que el utiliza durante la clase no la brinda al estudiante. Si es su primera experiencia en programar esta es su peor opcion.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2021-12-27T00:00:00+00:00'::TIMESTAMPTZ, '1c6217e12f515ce97a24055ecbae16c4e142e2514b2dcf5938076e46febfa08a'::TEXT, ARRAY[2511, 2513]::BIGINT[]),
    (695::BIGINT, 'Pésimo'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico']::TEXT[], '2021-11-25T00:00:00+00:00'::TIMESTAMPTZ, '93b17b056ded62d9673a1cbcfbee35c85bcd518766163939285babaa2c52c38b'::TEXT, ARRAY[1163]::BIGINT[]),
    (695::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-11-24T00:00:00+00:00'::TIMESTAMPTZ, 'fce8d678b038b893ed369b633eb4268074c686c801622ec75bdf8b5aaa0c5318'::TEXT, ARRAY[1163]::BIGINT[]),
    (695::BIGINT, 'Si se pone atención y se esfuerza se aprende demasiado con el. Califica muy duro y deja trabajos muy largos pero lo que uno aprende, lo aprende de verdad. Hagan todas las tareas morales que deje y pongan mucha atención si matriculan con el.'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2021-07-20T00:00:00+00:00'::TIMESTAMPTZ, 'ad7f21a9ea39235a86a7f238a19ba6bb94d9177b195a0b9fbccdcd7124738e35'::TEXT, ARRAY[2511, 2513]::BIGINT[]),
    (695::BIGINT, 'Profesor sumamente desordenado, sumamente malo y no ayuda en nada. No sabe explicar, explica como si fuera repaso de la materia, un profesor de programación al que no vi programar ni una sola vez. No divide bien el tiempo y en las ultimas semanas ve todos los temas y hace 4 exámenes'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2021-07-17T00:00:00+00:00'::TIMESTAMPTZ, 'fa241bab5d1339c67f3a431ed508cefe09048757ce555e5b7685fedcbb9c07c7'::TEXT, ARRAY[2511, 2513]::BIGINT[]),
    (695::BIGINT, 'No es un buen profesor pese a lo que dice aqui en la dificultad es un culiador no quiere a nadie y es un desordenado'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2021-07-14T00:00:00+00:00'::TIMESTAMPTZ, 'bcb15d11c0f611a17e735413222e2776543642c6483482f023183207b228d229'::TEXT, ARRAY[2511]::BIGINT[]),
    (695::BIGINT, 'NO! Aunque no haya otra opción, NO MATRICULE CON MILTON! Hágase un favor para su salud mental'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Exámenes retadores']::TEXT[], '2021-05-04T00:00:00+00:00'::TIMESTAMPTZ, 'be992def048a5d30374792f47e54ba22eb315fd2623f604862f916241af3ac05'::TEXT, ARRAY[2511, 2513]::BIGINT[]),
    (695::BIGINT, 'Es un profe bastante bueno, pero los exámenes y progras son muy duras, los asistentes califican los exámenes, HAGA LAS TAREAS MORALES y ponga atención en lo que dice que va a salir en el examen, porque VA A SALIR, póngale mucho desde el inicio para que su ponderado no se vaya a la mierda.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-02T00:00:00+00:00'::TIMESTAMPTZ, '4ed741b776397f6b7c87af036e3627d77567daa48b54af9423e45f3c27e13a3a'::TEXT, ARRAY[2511, 2513]::BIGINT[]),
    (695::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas']::TEXT[], '2020-12-09T00:00:00+00:00'::TIMESTAMPTZ, '9a7c91dd527328919d1f60ed3636989dc58e8429c5454e4d85ab5aeb58524597'::TEXT, ARRAY[2511, 2513]::BIGINT[]),
    (695::BIGINT, 'Ok, Milton es un amor, le pone ganas, y te va a ense;ar un monton. Eso si, es un dolor al calificar y al hacer examenes. Rudo Rudo jajaj pero se puede. Si matriculan con el pidan ayuda a ex estudiantes de él, nosotrxs entendemos el dolor jaja. HAGA LAS TAREAS MORALES'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Da buena retroalimentación']::TEXT[], '2020-09-04T00:00:00+00:00'::TIMESTAMPTZ, '4af521788087f20e632c6891bb481f37f2ae3a1638382137a94ed327245d7b3b'::TEXT, ARRAY[2511, 2513]::BIGINT[]),
    (695::BIGINT, 'Es un profe bastante difícil, califica duro, y jure que su promedio ponderado se va a ir al piso si es que pasa.Dejando eso de lado uno aprende muchísimo y realmente queda preparado para los otros cursos, su manera de explicar es peculiar pero buena.Los proyectos son difíciles, lo mandan a la guerra'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Respetado por los estudiantes', 'Deja trabajos largos']::TEXT[], '2020-08-11T00:00:00+00:00'::TIMESTAMPTZ, 'ae82aa4cd6a2c2183a81e8a099ec62d1d5de8e75b9987d9f87a092db48795ecc'::TEXT, ARRAY[2511, 2513]::BIGINT[]),
    (695::BIGINT, 'Se aprende muchísimo, pero el profe exige bastante. No le tenga miedo, téngale respeto a la materia. La gente habla mucha caca, pero usualmente es la falta de disciplina lo que dificulta el curso. El curso es de primer semestre, el profe es un primer choque con el mundo universitario'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-25T00:00:00+00:00'::TIMESTAMPTZ, 'e6239d2791a3e7cb4c008789f72795432e33b13d70094aeafbef03dcfad3933c'::TEXT, ARRAY[2513, 2511]::BIGINT[]),
    (695::BIGINT, 'Tiene mucho que hacer entonces a veces es un poco desordenado, pero enseña y sabe demasiado, haga las tareas morales y empiece los proyectos con tiempo'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Respetado por los estudiantes']::TEXT[], '2019-08-17T00:00:00+00:00'::TIMESTAMPTZ, 'fdf7dd57e318f3eea1ea2870285cfd9c1718649bbe2f84f276fb8e1206280f7c'::TEXT, ARRAY[2511, 2513]::BIGINT[]),
    (695::BIGINT, 'Es un buen profesor, como es coordinador a veces no esta, pero lo que enseña se aprende tan bien que esas pocas clases que no se reponen, no importan'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2019-08-17T00:00:00+00:00'::TIMESTAMPTZ, '161e0e2301d7752115f066954b67fb379558f27a06b88627ee6359da39e64696'::TEXT, ARRAY[2511, 2513]::BIGINT[]),
    (695::BIGINT, 'Cursos son difíciles, pero se aprende mucho con él.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo', 'Exámenes retadores']::TEXT[], '2019-08-08T00:00:00+00:00'::TIMESTAMPTZ, 'be86306afa7ef08cb117456d35c30839e6c15f30879da2154a2b09d4e43b6619'::TEXT, ARRAY[2969]::BIGINT[]),
    (695::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'd68c132990750f59b07eed867ed5718bfc95dd7f9a9c50e16960b63aad4894fd'::TEXT, ARRAY[2511]::BIGINT[]),
    (695::BIGINT, 'Es un profe demasiado desorganizado, como es coordinador de carrera nunca puede dar clases porque tiene otras cosas que hacer. Los proyectos nunca tienen que ver con la materia vista sino con un taller que da el asistente que ni explica bien y lo da por encima. Hace ir domigos'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2019-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'd81877f8c1d6ef4b8828e1116580be0f42bfc21c5fad0535790988eced0e8a9a'::TEXT, ARRAY[2511, 2513]::BIGINT[]),
    (695::BIGINT, 'Casi nunca está presente y todo se tiene que hablar c el asistente, el cual no sabe lo que hace. Como es coordinador de la carrera no se puede enfocar en ser profesor. No ajusta la calificación acordemente y por tanto la clase se vuelve pesada. Aún así se aprende mucho de él.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Respetado por los estudiantes', 'Muchos proyectos grupales']::TEXT[], '2019-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'acf4d1622a7bfab8a9ee2d2c22ce73599fe6a55195c1a3ab52d1dddd1d248bb5'::TEXT, ARRAY[2511, 2513]::BIGINT[]),
    (695::BIGINT, 'Excelente profesor, enseña bastante bien. El trabajo y lo que usted estudie importa bastante, hay que dedicarle muchas horas. Pero de seguro aprenderá bien y quedara fogueado para el siguiente curso. Los examenes son muy dificiles y largo, tiene que practicar con tiempo y con las tareas morales'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Exámenes retadores']::TEXT[], '2018-11-17T00:00:00+00:00'::TIMESTAMPTZ, '4afadf339b027cb741ac6d56ef8b349ef2625f8349d9220514749ecc1a8bfe50'::TEXT, ARRAY[2511]::BIGINT[]),
    (695::BIGINT, 'Un muy buen profesor, no regala el curso, pero si se esfuerza y hace las tareas morales, aprueba sin problemas. Clases muy entretenidas.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'e31ea578034de92eff1c3dad97e9858be5fbd9683abf8d0f2e35fb90792809d8'::TEXT, ARRAY[2511, 2513]::BIGINT[]),
    (695::BIGINT, 'Excelente profesor, está completamente interesado en el aprendizaje del estudiante, si se realizan todas la tareas morales los exámenes de hacen mucho más fáciles, las clases no son pesadas y siempre está dispuesto a ayudar. Sin duda llevaría con él otra vez, es solo ser responsable y participativo.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'b7a311f5d422b77275c91bceec5e8e2f7eb8da8e5fa6787b48dbe9996f63f427'::TEXT, ARRAY[2511, 2513]::BIGINT[]),
    (695::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Brinda apoyo']::TEXT[], '2018-05-22T00:00:00+00:00'::TIMESTAMPTZ, '06c3b62951e21d3b841192e107e93ea80ac74eaa5f869795cb63007ff8855b2a'::TEXT, ARRAY[2511]::BIGINT[]),
    (695::BIGINT, 'Tremendo profesor, pero no regala el curso. Definitivamente llevaría otra vez con él, por más difícil que sea.'::TEXT, 2.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2018-05-22T00:00:00+00:00'::TIMESTAMPTZ, '3ebd4126467728250fdf33836f5ae4df55b12090045b4b27f0a08d1db24f117d'::TEXT, ARRAY[2511]::BIGINT[]),
    (695::BIGINT, 'Cuesta llevarle el hilo de la explicación, eso si le pide ayuda por aparte el le va a explicar, tiene que ser muy autodidacta y buscar practicas por su cuenta, es buena persona y profesional pero no tan buen profe Se traba mucho en ciertos temas y luego corre en otros'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-05-03T00:00:00+00:00'::TIMESTAMPTZ, '7fa194b7f13bb4b23c8f1bd1b23a54a4e87385916d7c9c4480e873b04a93c5d7'::TEXT, ARRAY[2511, 2513]::BIGINT[]),
    (695::BIGINT, 'El profe sabe mucho, aunque se le dificulta transmitir ese conocimiento a los estudiantes. Es un poco irresponsable con las fechas. Usted tiene que ser algo autodidacta.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da crédito extra', 'Exámenes retadores']::TEXT[], '2017-06-14T00:00:00+00:00'::TIMESTAMPTZ, '6972b5e682822b59a8a03b23c1dfa8451240f176e2a5093d1c27f400cb8b6f9a'::TEXT, ARRAY[2511, 2513]::BIGINT[]),
    (695::BIGINT, 'No es un curso fácil, no regala nada pero si da muchas oportunidades para ganar puntos extra, se debe poner mucho esfuerzo para lograrlo, las clases son entretenidas.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-31T00:00:00+00:00'::TIMESTAMPTZ, 'd0ddd3afbb2a680442b61224b117ad50bbdc5043dce8394f873c8d41756e4007'::TEXT, ARRAY[2511, 2513]::BIGINT[]),
    (695::BIGINT, 'Muchas tareas a mano y proyectos que no devuelve, exámenes un poco difíciles pero te deja hacer un forro.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos']::TEXT[], '2017-01-26T00:00:00+00:00'::TIMESTAMPTZ, '36801cac425d3f509ce84e3c546430115a73bda58b76ad53bea4590cfd639213'::TEXT, ARRAY[2969]::BIGINT[]),
    (695::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores', 'La participación importa']::TEXT[], '2017-01-18T00:00:00+00:00'::TIMESTAMPTZ, 'a4b75199cd9866935ef8aac389074f9b42e9e67d6f878a29388fa6f48847ef06'::TEXT, ARRAY[2511, 2513]::BIGINT[]),
    (695::BIGINT, 'Manda muchas tareas (a mano) que nunca devuelve, hace exámenes pasables que tampoco devuelve, se hacen varios proyectos pero nada del otro mundo (tampoco los devuelve), se aprende a analizar tecnología y a realizar informes. Si el curso fuese de análisis de Tecnología seria el profe ideal.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Muchas tareas']::TEXT[], '2016-12-07T00:00:00+00:00'::TIMESTAMPTZ, 'f3122dcef7995ddd2e555a59bb6518015b48e62fe9e4395303b62495552600b4'::TEXT, ARRAY[2969]::BIGINT[]),
    (695::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2016-09-17T00:00:00+00:00'::TIMESTAMPTZ, '6ac62c16ab1f9a0ba2ae2298d82fb460ca2273d866213df01ead6ee172dcd10d'::TEXT, ARRAY[2511, 2513]::BIGINT[]),
    (695::BIGINT, 'Es muy difícil, hay que investigar y trabajar mucho fuera de la clase. Los exámenes son muy duros. Al final, luego de exprimir al máximo a los estudiantes, ayuda bastante con puntos.'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-28T00:00:00+00:00'::TIMESTAMPTZ, '43c6040f0ace217ab3650b4dd8c999a8e0770f0a84d5508d83247327ed7f3d8c'::TEXT, ARRAY[2511, 2513]::BIGINT[]),
    (695::BIGINT, 'Este profesor es un ícono de la carrera. Si bien es cierto su materia no es un paseo por el parque, para nada, no es imposible. Él va a dejar trabajos duros, va a hacer inclusive varios quices sorpresas por clase, va a hacer defensas duras, pero él evalúa el coraje y la persistencia. LA curva!'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Inspirador', 'Da crédito extra']::TEXT[], '2016-06-23T00:00:00+00:00'::TIMESTAMPTZ, '867a37d9756228297b93280ae736f858c8c50d23904a24a7d592d5dcef93dee0'::TEXT, ARRAY[2511]::BIGINT[]),
    (695::BIGINT, 'Pesimo profesor, cree que todo lo enseña uno lo sabe desde el cole y por ende no explica, nunca llega a clases, pero lo hace venir a reponer en findes, los examenes los entrega hasta el ultimo dia y por eso uno no sabe como va,o que debe afinar para proximos examenes, no pierda el tiempo con el.'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-28T00:00:00+00:00'::TIMESTAMPTZ, 'd19db142cbf64e5119e36b33f0ebc2814670aa6714bbdb0adc1162f41f67cf6c'::TEXT, ARRAY[2969]::BIGINT[]),
    (695::BIGINT, 'Este profesor es de esos tipicos que tienen argolla, es demasiado rudo para calificar y los examenes son muy difíciles... Las clases son una mediocridad y siempre llegaba tarde, por lo q habia que ir los sabados y domingos a clases a reponer tiempo que él mismo perdia. Los examenes pretendia hacerlos a las 9pm. De 25 pasan sólo 10 maxi'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('5','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2015-07-16T00:00:00+00:00'::TIMESTAMPTZ, '9e023579f935e33ad77f31eb71ea2b1e6f3acfe13ca513a9b20dbe20e2a0cbad'::TEXT, ARRAY[2511, 2513]::BIGINT[]),
    (695::BIGINT, 'Buen profesor, es realmente exigente especialmente con los proyectos pero se aprende muchísimo y si ayuda pero solo a los estudiantes que realmente le pusieron todo el semestre'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'bf139f6a6b6426c1a3a2b55580875d0fb7b8a950d9b44cfe229345e47e3826ef'::TEXT, ARRAY[2511, 2513]::BIGINT[]),
    (695::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-25T00:00:00+00:00'::TIMESTAMPTZ, '52e6793497f9dd8fcdfe0f9b33b0501562630f1c96b67053ad64f976c86e65cb'::TEXT, ARRAY[2511, 2513]::BIGINT[]),
    (695::BIGINT, 'Es duro pero si se logra pasarle. Investigar todo lo que el dice durante las lecciones. Se vacila bastante en las calses. Casi no deja tareas. Los examenes son dificiles. Se aprende demasiado con el.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-25T00:00:00+00:00'::TIMESTAMPTZ, '44e732cf34076afb3eaaa201dc2b7055c795c9f27054acb416193861223f1bd7'::TEXT, ARRAY[2511, 2513]::BIGINT[]),
    (695::BIGINT, 'Es rudo y exige mucho tiempo, pero te prepara muy bien, aveces le cuesta darse a entender pero si tiene que explicarlo varias veces lo hace. Es muy buena gente y ayuda a los estudiantes que le ponen bastante, si te gusta la carrera las classes no son para nada aburridas.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-27T00:00:00+00:00'::TIMESTAMPTZ, 'a8cdcfd3d9bbcaf512ce15bbb25a3ca3b0325aaa36f364961f9e5bc6b21768fe'::TEXT, ARRAY[2511, 2513]::BIGINT[]),
    (695::BIGINT, 'Es un excelente Profesor, se preocupa por que uno aprenda, pero hay que trabajar bastante, al final uno aprende mucho.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-25T00:00:00+00:00'::TIMESTAMPTZ, '9823fa92689c0cad4595dfd334cace92e70e68c15966b7a396de1eb998fcd697'::TEXT, ARRAY[2511, 2513]::BIGINT[]),
    (695::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-03-09T00:00:00+00:00'::TIMESTAMPTZ, '2f39c2dcbf5eddc0d8b74de45bb68767b15adb5aaf3059948b1b3bb9269a05fe'::TEXT, ARRAY[2511, 2513]::BIGINT[]),
    (695::BIGINT, 'No sabe enseñar humilla a la gente y esas varitas de hacer clases feriados, domingos examenes hasta media noche es una estupidez'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-29T00:00:00+00:00'::TIMESTAMPTZ, 'c7c3c7eb22e34df7112c4e3c42c35f7c8faaafc5d4badd761fb7c83f639a14ef'::TEXT, ARRAY[2511]::BIGINT[]),
    (695::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-20T00:00:00+00:00'::TIMESTAMPTZ, '6ccffda201ffeebbf2ff57770dd97310d6379dfaacd7fc574c0b3b17f1b7ba4c'::TEXT, ARRAY[2511]::BIGINT[]),
    (695::BIGINT, 'En todas los cursos, en general, abarca tantos temas que no se aprende bien de ninguno en específico. Al ser obligado a aprender por cuenta propia de tantísimas ramas, se aprende lo superficial, y uno queda con un montón de huecos, de bases que no se dieron. Se aprende de todo, pero por encima y mal'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-25T00:00:00+00:00'::TIMESTAMPTZ, 'a269050be4bcb5c86e4859d6b96153caf02c83479e9efd541027cc7386e543d7'::TEXT, ARRAY[2511]::BIGINT[]),
    (695::BIGINT, 'Hay que ponerle para pasarle y organizarse bien con el tiempo, pero va a aprender mucho y se va a reír bastante.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-22T00:00:00+00:00'::TIMESTAMPTZ, '56cca3ac98bcaf6d087dc5c2382c0bf7d218ec4841d89c42aa27c41051e4898e'::TEXT, ARRAY[2511]::BIGINT[]),
    (695::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-22T00:00:00+00:00'::TIMESTAMPTZ, 'c58d5d31c56f246f9a8d2d864dbe07750f9b93bea9352539420f641bd7235e12'::TEXT, ARRAY[2511, 2513]::BIGINT[]),
    (695::BIGINT, 'Es bastante difícil pero enseña más que cualquier otro profe. Las clases son entretenidas, es gracioso.'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, '5a5286a6066554086c67a84409533bb6cee39405308682e9a19dbc940104b5c4'::TEXT, ARRAY[2511, 2513]::BIGINT[]),
    (695::BIGINT, 'Es un profe para que usted entienda lo que es estar en una universidad de calidad como el TEC. Es muy exigente pero se aprende muchísimo.'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, 'a4ae5b0cbce72d7f8480f5127ff636b889796820118668da74d71f8e415ee072'::TEXT, ARRAY[2511, 2513]::BIGINT[]),
    (695::BIGINT, 'Recomiendo este profe si en realidad quieren pasar sin dormir unas cuantos dias por semana, los examenes son muy duros y las clases son complicadas de entender, sin embargo trata de enseñar las cosas bien y enseña mucho, para pasar hay que dedicarle mucho tiempo al curso (unos 8 creditos xD)'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, 'fc0998bf9d4b3bfd187f2c792149e311bf276a735996389599032546a54635d6'::TEXT, ARRAY[2511, 2513]::BIGINT[]),
    (695::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, '1c7fbbf35ce361facfdaa44cd759cf7a7202231800d392d6cfd080921c92b5c8'::TEXT, ARRAY[2511]::BIGINT[]),
    (695::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '6ed7fefa040aeaf619f317d5e484302fb3a947543c72806c1d960f7f3cca5353'::TEXT, ARRAY[2511, 2513]::BIGINT[]),
    (695::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '7fb7f95d14e76f80d73edcd4ab292fdb3504236bdc6f0b80be8296f191edf94e'::TEXT, ARRAY[2519, 2518]::BIGINT[]),
    (695::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '042454db342aab2b37622a879d3491558671d4be604f8254a5c466ead7244c4f'::TEXT, ARRAY[2511]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
